//! OpenViz – a free and open-source desktop app for exploring data
//! with drag-and-drop charts and dashboards.

mod app;
mod chart;
mod data;
mod expr;
mod model;
mod paint;

fn main() -> eframe::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let mut screenshot: Option<String> = None;
    let mut open: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--screenshot" => {
                screenshot = args.get(i + 1).cloned();
                i += 1;
            }
            "--help" | "-h" => {
                println!("OpenViz – explore data with drag-and-drop charts\n\nUsage: openviz [FILE.csv | WORKBOOK.ovw] [--screenshot OUT.png]");
                return Ok(());
            }
            other => open = Some(other.to_string()),
        }
        i += 1;
    }
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_title("OpenViz")
            .with_inner_size([1440.0, 900.0])
            .with_min_inner_size([900.0, 560.0]),
        ..Default::default()
    };
    eframe::run_native(
        "OpenViz",
        options,
        Box::new(move |cc| Ok(Box::new(app::App::new(cc, open, screenshot)))),
    )
}

