import struct, sys
def cmap(path):
    d=open(path,'rb').read()
    n=struct.unpack('>H',d[4:6])[0]
    off=None
    for i in range(n):
        tag,_,o,_=struct.unpack('>4sIII',d[12+16*i:28+16*i])
        if tag==b'cmap': off=o
    nt=struct.unpack('>H',d[off+2:off+4])[0]
    cps=set()
    for i in range(nt):
        pid,eid,so=struct.unpack('>HHI',d[off+4+8*i:off+12+8*i])
        s=off+so; fmt=struct.unpack('>H',d[s:s+2])[0]
        if fmt==4:
            segx2=struct.unpack('>H',d[s+6:s+8])[0]; seg=segx2//2
            ends=struct.unpack('>%dH'%seg,d[s+14:s+14+segx2])
            starts=struct.unpack('>%dH'%seg,d[s+16+segx2:s+16+2*segx2])
            for a,b in zip(starts,ends):
                if a!=0xFFFF: cps.update(range(a,b+1))
        elif fmt==12:
            ng=struct.unpack('>I',d[s+12:s+16])[0]
            for g in range(ng):
                a,b,_=struct.unpack('>III',d[s+16+12*g:s+28+12*g]); cps.update(range(a,b+1))
    return cps
F=sys.argv[1]
fonts={n:cmap(F+'/'+n) for n in ['Ubuntu-Light.ttf','NotoEmoji-Regular.ttf','emoji-icon-font.ttf']}
for ch in sys.argv[2]:
    print(ch, hex(ord(ch)), [n[:5] for n,c in fonts.items() if ord(ch) in c])
EOF
